//! Loop goldens from the reference tmux 3.8, regenerated by `tests/loop_cases.sh` into
//! `loop_rows.in`, over a test double of the topology that script builds: 3 sessions,
//! 4 windows in the target session, 5 panes in its current window, 2 clients.

use super::{
    EnvScope, EnvVar, FixedWallClock, FormatContext, LoopItem, LoopKeys, LoopOption, OptionScope,
    OptionsLoop, expand_time_at,
};

include!("loop_rows.in");

fn r(template: &str, expected: &str) -> (String, String) {
    (template.to_owned(), expected.to_owned())
}

struct Pane {
    id: u32,
    title: &'static str,
    /// `window_pane_zindex`: the floating pane is 0, tiled panes under it 2.
    z: u32,
}

struct Window {
    id: u32,
    index: u32,
    name: &'static str,
    /// Newest first in the reference: bravo (selected), alpha, delta, charlie.
    activity: u64,
    /// Window order (`pane_index` is the position).
    panes: Vec<Pane>,
    active: u32,
    options: Vec<(&'static str, &'static str)>,
}

struct Session {
    id: u32,
    name: &'static str,
    activity: u64,
    windows: Vec<Window>,
    current: u32,
}

struct Client {
    name: &'static str,
    session: usize,
    activity: u64,
}

struct Topology {
    /// In the server's order (by name), as `sort_get_sessions` walks them.
    sessions: Vec<Session>,
    clients: Vec<Client>,
}

fn opt(name: &str, value: &str) -> LoopOption {
    LoopOption {
        name: name.to_owned(),
        value: value.to_owned(),
        array: None,
        hook: false,
        user: name.starts_with('@'),
    }
}

fn array(name: &str, items: &[(&str, &str)], hook: bool) -> LoopOption {
    LoopOption {
        name: name.to_owned(),
        value: items.iter().map(|(_, v)| *v).collect::<Vec<_>>().join(" "),
        array: Some(
            items
                .iter()
                .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
                .collect(),
        ),
        hook,
        user: false,
    }
}

fn single_pane(id: u32) -> Vec<Pane> {
    vec![Pane {
        id,
        title: ["t0", "t1", "t2", "", "t4", "t5"][id as usize],
        z: 1,
    }]
}

fn topology() -> Topology {
    let window = |id, index, name, activity, panes: Vec<Pane>, options| Window {
        id,
        index,
        name,
        activity,
        active: panes[0].id,
        panes,
        options,
    };
    let bravo = Window {
        active: 6,
        ..window(
            3,
            2,
            "bravo",
            40,
            vec![
                Pane {
                    id: 7,
                    title: "t7",
                    z: 2,
                },
                Pane {
                    id: 3,
                    title: "t3",
                    z: 2,
                },
                Pane {
                    id: 6,
                    title: "t6",
                    z: 2,
                },
                Pane {
                    id: 8,
                    title: "t8",
                    z: 2,
                },
                Pane {
                    id: 9,
                    title: "t9",
                    z: 0,
                },
            ],
            vec![("@wv", "y")],
        )
    };
    let zeta = Session {
        id: 0,
        name: "zeta",
        activity: 50,
        current: 2,
        windows: vec![
            window(0, 0, "charlie", 10, single_pane(0), vec![("@other", "o0")]),
            window(5, 1, "alpha", 30, single_pane(5), vec![("@tag", "a1")]),
            bravo,
            window(4, 4, "delta", 20, single_pane(4), vec![("@tag", "d4")]),
        ],
    };
    let one = |id, name, activity| Session {
        id,
        name,
        activity,
        current: 0,
        windows: vec![window(id, 0, "w", 0, single_pane(id), vec![])],
    };
    Topology {
        sessions: vec![one(1, "alpha", 60), one(2, "mike", 5), zeta],
        clients: vec![
            Client {
                name: "client-1",
                session: 2,
                activity: 50,
            },
            Client {
                name: "client-2",
                session: 0,
                activity: 60,
            },
        ],
    }
}

/// `format_defaults(c, s, wl, wp)` over the double, missing parts filled from the
/// session (format.c:7015-7020).
#[derive(Clone, Copy)]
struct Ctx<'a> {
    topo: &'a Topology,
    session: Option<usize>,
    window: Option<usize>,
    pane: Option<usize>,
    client: Option<usize>,
}

impl<'a> Ctx<'a> {
    fn new(
        topo: &'a Topology,
        session: Option<usize>,
        window: Option<usize>,
        pane: Option<usize>,
        client: Option<usize>,
    ) -> Self {
        let s = session.map(|s| &topo.sessions[s]);
        let window =
            window.or_else(|| s.and_then(|s| s.windows.iter().position(|w| w.index == s.current)));
        let w = s.zip(window).map(|(s, w)| &s.windows[w]);
        let pane = pane.or_else(|| w.and_then(|w| w.panes.iter().position(|p| p.id == w.active)));
        Self {
            topo,
            session,
            window,
            pane,
            client,
        }
    }

    fn s(&self) -> Option<&'a Session> {
        Some(&self.topo.sessions[self.session?])
    }

    fn w(&self) -> Option<&'a Window> {
        Some(&self.s()?.windows[self.window?])
    }

    fn p(&self) -> Option<&'a Pane> {
        Some(&self.w()?.panes[self.pane?])
    }
}

fn item(ctx: Ctx<'_>, keys: LoopKeys) -> LoopItem<'_> {
    LoopItem {
        ctx: Box::new(ctx),
        keys,
    }
}

fn flag(b: bool) -> String {
    String::from(if b { "1" } else { "0" })
}

impl FormatContext for Ctx<'_> {
    fn get(&self, name: &str) -> Option<String> {
        let (s, w, p) = (self.s(), self.w(), self.p());
        let c = self.client.map(|c| &self.topo.clients[c]);
        Some(match name {
            "client_name" => c?.name.to_owned(),
            "client_session" => self.topo.sessions[c?.session].name.to_owned(),
            "session_name" => s?.name.to_owned(),
            "session_id" => format!("${}", s?.id),
            "window_name" => w?.name.to_owned(),
            "window_index" => w?.index.to_string(),
            "window_active" => flag(s?.current == w?.index),
            "pane_id" => format!("%{}", p?.id),
            "pane_title" => p?.title.to_owned(),
            "pane_active" => flag(w?.active == p?.id),
            "pane_index" => {
                let id = p?.id;
                w?.panes.iter().position(|x| x.id == id)?.to_string()
            }
            _ => {
                return w?
                    .options
                    .iter()
                    .find(|(k, _)| *k == name)
                    .map(|(_, v)| (*v).to_owned());
            }
        })
    }

    fn environ(&self, scope: EnvScope) -> Option<Vec<EnvVar>> {
        // Attaching to zeta applied its update-environment: FOO and BAR, both unset.
        let removed = |name: &str| EnvVar {
            name: name.to_owned(),
            value: None,
            hidden: false,
        };
        match scope {
            EnvScope::Session if self.s()?.name == "zeta" => {
                Some(vec![removed("BAR"), removed("FOO")])
            }
            _ => None,
        }
    }

    fn sessions(&self) -> Vec<LoopItem<'_>> {
        let current = self.client.map(|c| self.topo.clients[c].session);
        self.topo
            .sessions
            .iter()
            .enumerate()
            .map(|(i, s)| {
                item(
                    Ctx::new(self.topo, Some(i), None, None, self.client),
                    LoopKeys {
                        active: current == Some(i),
                        id: s.id,
                        name: s.name.to_owned(),
                        activity: s.activity,
                        ..LoopKeys::default()
                    },
                )
            })
            .collect()
    }

    fn windows(&self) -> Option<Vec<LoopItem<'_>>> {
        let s = self.s()?;
        Some(
            s.windows
                .iter()
                .enumerate()
                .map(|(i, w)| {
                    item(
                        Ctx::new(self.topo, self.session, Some(i), None, self.client),
                        LoopKeys {
                            active: s.current == w.index,
                            id: w.id,
                            index: w.index,
                            name: w.name.to_owned(),
                            activity: w.activity,
                            user_options: w
                                .options
                                .iter()
                                .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
                                .collect(),
                            ..LoopKeys::default()
                        },
                    )
                })
                .collect(),
        )
    }

    fn panes(&self) -> Option<Vec<LoopItem<'_>>> {
        let w = self.w()?;
        Some(
            w.panes
                .iter()
                .enumerate()
                .map(|(i, p)| {
                    item(
                        Ctx::new(self.topo, self.session, self.window, Some(i), self.client),
                        LoopKeys {
                            active: w.active == p.id,
                            id: p.id,
                            index: u32::try_from(i).unwrap(),
                            name: p.title.to_owned(),
                            z: p.z,
                            ..LoopKeys::default()
                        },
                    )
                })
                .collect(),
        )
    }

    fn clients(&self) -> Vec<LoopItem<'_>> {
        self.topo
            .clients
            .iter()
            .enumerate()
            .map(|(i, c)| {
                let mut ctx = *self;
                ctx.client = Some(i);
                item(
                    ctx,
                    LoopKeys {
                        id: u32::try_from(i).unwrap(),
                        name: c.name.to_owned(),
                        activity: c.activity,
                        ..LoopKeys::default()
                    },
                )
            })
            .collect()
    }

    fn options(&self, scope: OptionScope) -> Option<OptionsLoop<'_>> {
        let entries = match scope {
            OptionScope::Server => vec![opt("@srv", "q"), opt("escape-time", "10")],
            OptionScope::GlobalSession => vec![opt("@gs1", "one"), opt("base-index", "0")],
            OptionScope::GlobalWindow => vec![opt("@gw1", "w1"), opt("mode-keys", "emacs")],
            OptionScope::Session if self.s()?.name == "zeta" => vec![
                opt("@sv", "x"),
                array("after-new-window", &[("0", "display-message x")], true),
                opt("default-size", "80x24"),
                array("status-format", &[], false),
                array("update-environment", &[("3", "FOO"), ("7", "BAR")], false),
            ],
            // `new-window -n` turned automatic-rename off in each window's own tree.
            OptionScope::Window => {
                let mut v: Vec<_> = self.w()?.options.iter().map(|(k, v)| opt(k, v)).collect();
                if self.s()?.name == "zeta" {
                    v.push(opt("automatic-rename", "off"));
                }
                v
            }
            OptionScope::Pane if self.p()?.id == 6 => vec![opt("@pv", "z")],
            _ => Vec::new(),
        };
        Some(OptionsLoop {
            ctx: Box::new(*self),
            entries,
        })
    }
}

fn check(ctx: &Ctx<'_>, rows: Vec<(String, String)>) {
    let wall = FixedWallClock::new(1_793_369_398, "UTC").expect("zoneinfo");
    let mut failures = Vec::new();
    for (template, expected) in rows {
        // display-message -p: a time-aware expansion; the rows have no `%`.
        let got = expand_time_at(&template, ctx, &wall);
        if got != expected {
            failures.push(format!("{template:?}: expected {expected:?}, got {got:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// `display -p -t zeta:` from the reference: zeta's best client is client-1.
#[test]
fn format_loop_rows_match_reference() {
    let topo = topology();
    check(&Ctx::new(&topo, Some(2), None, None, Some(0)), rows());
}

/// No session, no client: `W` and `P` end the expansion, the rest are empty.
#[test]
fn format_loop_rows_without_a_session_match_reference() {
    struct Empty;
    impl FormatContext for Empty {
        fn get(&self, _: &str) -> Option<String> {
            None
        }
    }
    let wall = FixedWallClock::new(0, "UTC").expect("zoneinfo");
    for (template, expected) in rows_nosession() {
        let got = super::expand_at(&super::parse(&template).ast, &Empty, &wall);
        assert_eq!(got, expected, "{template:?}");
    }
}
